SELECT i.id, i.warehouse_id, i.warehouse_area_id, i.warehouse_area_loca_id, i.consignor_id, i.sku_id, i.batch_number, i.prod_date, i.expire_date, i.quality_status, i.total_count, i.available_count, i.locked_count, i.frozen_count, i.used_volume, i.used_weight, i.version, i.create_time, i.create_by, i.update_time, i.update_by, w.name AS warehouse_name, a.name AS area_name, l.loca_code, l.storage_condition, p.sub_title AS spu_code, s.code AS sku_code, p.title AS spu_title, c.consignor_name AS consignor_name, AS expire_status FROM wms_inventory i LEFT JOIN wms_warehouse w ON w.id = i.warehouse_id LEFT JOIN wms_warehouse_area a ON a.id = i.warehouse_area_id LEFT JOIN wms_warehouse_area_loca l ON l.id = i.warehouse_area_loca_id LEFT JOIN wms_item_sku s ON s.id = i.sku_id LEFT JOIN wms_item_spu p ON p.id = s.spu_id LEFT JOIN wms_consignor c ON c.id = i.consignor_id WHERE i.is_del = 1
AND i.warehouse_id = #{q.warehouseId}
AND i.warehouse_area_id = #{q.warehouseAreaId}
AND i.warehouse_area_loca_id = #{q.warehouseAreaLocaId}
AND i.consignor_id = #{q.consignorId}
AND i.sku_id = #{q.skuId}
AND s.code LIKE CONCAT('%', #{q.skuCode}, '%')
AND p.sub_title LIKE CONCAT('%', #{q.spuCode}, '%')
AND p.title LIKE CONCAT('%', #{q.spuTitle}, '%')
AND i.batch_number = #{q.batchNumber}
AND i.quality_status = #{q.qualityStatus}
AND l.storage_condition = #{q.storageCondition}
AND = #{q.expireStatus}
AND l.loca_code LIKE CONCAT('%', #{q.locaCode}, '%')
AND EXISTS ( SELECT 1 FROM wms_item_sn sn WHERE sn.warehouse_area_loca_id = i.warehouse_area_loca_id AND sn.sku_id = i.sku_id AND sn.batch_number = i.batch_number AND sn.sn_code LIKE CONCAT('%', #{q.snCode}, '%') AND sn.is_del = 1 )
AND i.total_count > 0
ORDER BY i.warehouse_id, i.warehouse_area_loca_id, i.sku_id, i.batch_number

SELECT *
FROM wms_inventory
WHERE warehouse_area_loca_id = #{d.warehouseAreaLocaId}
  AND sku_id = #{d.skuId}
  AND batch_number = #{d.batchNumberOrDefault}
  AND consignor_id = #{d.consignorIdOrDefault}
  AND quality_status = #{d.qualityStatusOrDefault}
LIMIT 1
FOR UPDATE

SELECT IFNULL(SUM(i.total_count), 0)
FROM wms_inventory i
WHERE i.is_del = 1

    AND i.warehouse_id = #{warehouseId}


    AND i.sku_id = #{skuId}
